mapper.select:
select b.batch_id as deptId, b.batch_no as batchNo, b.batch_name as batchName, b.year_month as yearMonth, b.pay_date as payDate, b.bank_name as bankName, b.total_count as totalCount, b.total_amount as totalAmount, b.audit_status as auditStatus, b.sealed_status as sealedStatus from biz_hr_payroll_batch b where b.del_flag = '0'
and b.year_month = #{yearMonth}
order by b.year_month desc, b.batch_id desc
